const listVideoRouteEnvelopes = `-- name: ListVideoRouteEnvelopes :many
SELECT id, video_envelope FROM model_routes WHERE id = ANY($1::uuid[])
`

type ListVideoRouteEnvelopesRow struct {
	ID            pgtype.UUID
	VideoEnvelope []byte
}

// The declared envelope of several routes at once.
//
// The console's job list needs one field off each row's route -- how far that
// job can still be stopped -- and asking per row turned a page of a hundred
// jobs into a hundred and one queries for a field most of those rows never
// render.
func (q *Queries) ListVideoRouteEnvelopes(ctx context.Context, ids []pgtype.UUID) ([]ListVideoRouteEnvelopesRow, error) {
	rows, err := q.db.Query(ctx, listVideoRouteEnvelopes, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListVideoRouteEnvelopesRow
	for rows.Next() {
		var i ListVideoRouteEnvelopesRow
		if err := rows.Scan(&i.ID, &i.VideoEnvelope); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

