const markVideoJobTerminal = `-- name: MarkVideoJobTerminal :execrows
UPDATE gateway_async_jobs
   SET status = $1, upstream_status = $2, terminal_at = now(),
       error_code = $3, error_message = $4,
       upstream_artifact_ref = $5,
       upstream_artifact_expires_at = $6,
       progress = CASE WHEN $1::text = 'completed' THEN 100 ELSE progress END,
       next_poll_at = NULL
 WHERE id = $7 AND status IN ('queued', 'in_progress')
`

type MarkVideoJobTerminalParams struct {
	Status                    string
	UpstreamStatus            string
	ErrorCode                 string
	ErrorMessage              string
	UpstreamArtifactRef       string
	UpstreamArtifactExpiresAt pgtype.Timestamptz
	ID                        pgtype.UUID
}

// The terminal transition and nothing else. Settlement is a separate statement
// in the same transaction, guarded on settlement_state, so that a crash between
// the two leaves a row the sweeper can still finish.
func (q *Queries) MarkVideoJobTerminal(ctx context.Context, arg MarkVideoJobTerminalParams) (int64, error) {
	result, err := q.db.Exec(ctx, markVideoJobTerminal,
		arg.Status,
		arg.UpstreamStatus,
		arg.ErrorCode,
		arg.ErrorMessage,
		arg.UpstreamArtifactRef,
		arg.UpstreamArtifactExpiresAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

